#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

// Create new node
struct Node* createNode(int value) {
    struct Node *newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// 1. Insert at Beginning
void insertAtBeginning(struct Node **head, int value) {
    struct Node *newNode = createNode(value);
    newNode->next = *head;  // newNode points to old head
    *head = newNode;        // head now points to newNode
}

// 2. Insert at End
void insertAtEnd(struct Node **head, int value) {
    struct Node *newNode = createNode(value);

    if (*head == NULL) {      // list empty
        *head = newNode;
        return;
    }

    struct Node *temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;    // move till last node
    }
    temp->next = newNode;     // attach newNode at end
}

// 3. Insert at Nth Position
void insertAtPosition(struct Node **head, int value, int position) {
    struct Node *newNode = createNode(value);

    // Case: insert at beginning
    if (position == 1) {
        newNode->next = *head;
        *head = newNode;
        return;
    }

    struct Node *temp = *head;
    for (int i = 1; i < position - 1 && temp != NULL; i++) {
        temp = temp->next;   // move to (pos-1)th node
    }

    if (temp == NULL) {
        printf("Position out of range!\n");
        free(newNode);
        return;
    }

    newNode->next = temp->next;
    temp->next = newNode;
}

// Print list
void printList(struct Node *head) {
    struct Node *temp = head;
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

// Main function
int main() {
    struct Node *head = NULL;   // start with empty list

    insertAtBeginning(&head, 10);   // 10
    insertAtEnd(&head, 20);         // 10 -> 20
    insertAtEnd(&head, 40);         // 10 -> 20 -> 40
