Nice, Boss 👌 — let’s now move to **Circular Linked List (CLL)** in C.  

I’ll keep it simple (like we did with SLL):  
- We’ll use a **`struct Node`** (no typedefs).  
- Write functions for **insert at beginning, insert at end, delete, and print**.  
- Show how it’s different from normal linked list.

---

## 🔹 What is a Circular Linked List?
- In **SLL**: last node’s `next = NULL`.  
- In **CLL**: last node’s `next = head` (points back to first).  

Example:
```
head → 10 → 20 → 30 → 40
          ↑             ↓
          └─────────────┘
```

---

## 🔹 Code for Circular Linked List

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

// Create new node
struct Node* createNode(int value) {
    struct Node *newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Insert at End
void insertAtEnd(struct Node **head, int value) {
    struct Node *newNode = createNode(value);

    if (*head == NULL) {
        *head = newNode;
        newNode->next = *head;   // points to itself
        return;
    }

    struct Node *temp = *head;
    while (temp->next != *head) {   // go till last node
        temp = temp->next;
    }
    temp->next = newNode;
    newNode->next = *head;   // close the circle
}

// Insert at Beginning
void insertAtBeginning(struct Node **head, int value) {
    struct Node *newNode = createNode(value);

    if (*head == NULL) {
        *head = newNode;
        newNode->next = *head;
        return;
    }

    struct Node *temp = *head;
    while (temp->next != *head) {   // go till last node
        temp = temp->next;
    }
    temp->next = newNode;
    newNode->next = *head;
    *head = newNode;   // new node becomes head
}

// Delete from Beginning
void deleteAtBeginning(struct Node **head) {
    if (*head == NULL) {
        printf("List is empty!\n");
        return;
    }

    if ((*head)->next == *head) {   // only 1 node
        free(*head);
        *head = NULL;
        return;
    }

    struct Node *last = *head;
    while (last->next != *head) {
        last = last->next;
    }

    struct Node *temp = *head;
    last->next = temp->next;   // last points to new head
    *head = temp->next;        // move head
    free(temp);
}

// Delete from End
void deleteAtEnd(struct Node **head) {
    if (*head == NULL) {
        printf("List is empty!\n");
        return;
    }

    if ((*head)->next == *head) {   // only 1 node
        free(*head);
        *head = NULL;
        return;
    }

    struct Node *temp = *head;
    while (temp->next->next != *head) {  // stop at second last
        temp = temp->next;
    }

    struct Node *last = temp->next;
    temp->next = *head;
    free(last);
}

// Print Circular Linked List
void printList(struct Node *head) {
    if (head == NULL) {
        printf("List is empty!\n");
        return;
    }

    struct Node *temp = head;
    do {
        printf("%d -> ", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("(back to head)\n");
}

// Main function
int main() {
    struct Node *head = NULL;

    insertAtEnd(&head, 10);
    insertAtEnd(&head, 20);
    insertAtEnd(&head, 30);
    insertAtBeginning(&head, 5);

    printList(head);   // Expected: 5 -> 10 -> 20 -> 30 -> (back to head)

    deleteAtBeginning(&head);
    printList(head);   // Expected: 10 -> 20 -> 30 -> (back to head)

    deleteAtEnd(&head);
    printList(head);   // Expected: 10 -> 20 -> (back to head)

    return 0;
}
```

---

## ✅ Sample Output
```
5 -> 10 -> 20 -> 30 -> (back to head)
10 -> 20 -> 30 -> (back to head)
10 -> 20 -> (back to head)
```

