    struct Node *newNode = createNode(value);

    if (*head == NULL) {   // empty list
        *head = newNode;
        return;
    }

    newNode->next = *head;  // newNode points forward
    (*head)->prev = newNode; // old head points back
    *head = newNode;        // move head to new node
}
```

