    struct Node *last = *head;
    while (last->next != *head) {   // find last node
        last = last->next;
    }

    struct Node *temp = *head;
    last->next = temp->next;        // last -> new head
    *head = temp->next;             // move head forward
    free(temp);                     // delete old head
}
